package com.asmrlib.archiver;

import android.util.Log;

import org.json.JSONArray;
import org.json.JSONObject;

import java.io.ByteArrayInputStream;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

import android.webkit.WebResourceRequest;
import android.webkit.WebResourceResponse;
import android.webkit.WebView;

/**
 * Port of the desktop online_shield.ShieldPolicy decisions to the APK shell.
 * Reads the same tables from assets/blocklist.json (generated by
 * `python -m asmrlib_archiver.mobile_blocklist` from security_lists.py, so
 * phone and desktop always block the same hosts).
 *
 * <p>Threading: {@link #intercept} runs on a Chromium worker thread while
 * {@link #shouldBlockNavigation} runs on the main thread, and the learned player
 * sets are written from both. Every set written after construction is therefore
 * a concurrent set — a plain HashSet read while another thread adds to it is a
 * latent hang, not a cosmetic detail. {@code appOrigins} is filled once in
 * {@link #fromAssets} and only read afterwards, so it stays a plain set.
 */
public final class ShieldRules {

    private static final String TAG = "asmrlib-shield";

    private final Set<String> playerDomains = java.util.concurrent.ConcurrentHashMap.newKeySet();
    private final Set<String> assetDomains = java.util.concurrent.ConcurrentHashMap.newKeySet();
    private final Set<String> blockedHosts = java.util.concurrent.ConcurrentHashMap.newKeySet();
    private final List<String> blockUrlKeywords = new ArrayList<>();
    private final Set<String> appOrigins = new HashSet<>();

    /**
     * Player hosts our own play page declared this session.
     *
     * <p>The player host rotates — it has at least once already — so a baked-in
     * list is permanently one rotation behind, and being behind used to mean the
     * page the user asked for never opened. The play page builds its
     * 「进入播放器」 link out of the site's own player markup, so the URL it hands
     * over is the *declared* one: the same trust anchor the save path validates
     * against. Registering that host keeps a rotation from turning into a dead
     * button.
     */
    private final Set<String> declaredPlayerHosts = java.util.concurrent.ConcurrentHashMap.newKeySet();

    /**
     * Sibling hosts learned by hopping out of a trusted player page.
     *
     * <p>This is the shape the BI source really uses: {@code bysetayico.com/e/<id>}
     * hands the frame to an unrelated sibling host
     * ({@code f7hyg4q.org/l3y/<id>}, {@code /segh/<id>}). Those siblings were
     * hand-added to the baked list one outage at a time — see the note in
     * security_lists.py — so without learning them the next rotation breaks
     * playback the same way, and this time it used to break it *silently*.
     *
     * <p>Kept separate from {@link #declaredPlayerHosts} on purpose: a host
     * learned this way may not open a further hop. Otherwise trust compounds, and
     * one advert that redirects the top frame would drag the whole ad network in
     * behind it — which is exactly what happened when this was a single set and
     * an experimental navigation to doubleclick.net got itself trusted.
     */
    private final Set<String> hoppedPlayerHosts = java.util.concurrent.ConcurrentHashMap.newKeySet();

    /**
     * Ceiling on how many hosts one session may learn, per route.
     *
     * <p>The two routes are already gated by trust — the play page's own declared
     * markup, or one hop out of an already-trusted page — but a redirect chain is
     * still a chain, and every hop of it would otherwise be attributed to the same
     * initiating document. Six is well above anything the known sources need (the
     * baked list holds four sibling hosts in total) and low enough that a hostile
     * page cannot walk a network into the allow-list one redirect at a time.
     */
    private static final int MAX_LEARNED_HOSTS = 6;

    public int blockedRequests = 0;
    public int blockedNavigations = 0;

    public static ShieldRules fromAssets(android.content.res.AssetManager assets,
                                         String serverUrl) {
        ShieldRules rules = new ShieldRules();
        try (java.io.InputStream in = assets.open("blocklist.json")) {
            byte[] buf = new byte[65536];
            StringBuilder sb = new StringBuilder();
            int n;
            while ((n = in.read(buf)) > 0) {
                sb.append(new String(buf, 0, n, "UTF-8"));
            }
            JSONObject root = new JSONObject(sb.toString());
            fill(rules.playerDomains, root.optJSONArray("player_domains"));
            fill(rules.assetDomains, root.optJSONArray("asset_domains"));
            fill(rules.blockedHosts, root.optJSONArray("blocked_hosts"));
            fill(rules.blockUrlKeywords, root.optJSONArray("block_url_keywords"));
        } catch (Exception e) {
            // Fail open for the server itself, fail closed for ads is not
            // possible without the list — log loudly; the JS-level CSP on
            // archive pages still protects archived content.
            Log.wtf(TAG, "blocklist.json missing or invalid: " + e);
        }
        if (serverUrl != null && !serverUrl.isEmpty()) {
            rules.appOrigins.add(hostOf(serverUrl));
        }
        return rules;
    }

    private static void fill(Set<String> target, JSONArray arr) {
        if (arr == null) return;
        for (int i = 0; i < arr.length(); i++) {
            String v = normalizeHost(arr.optString(i, ""));
            if (!v.isEmpty()) target.add(v);
        }
    }

    private static void fill(List<String> target, JSONArray arr) {
        if (arr == null) return;
        for (int i = 0; i < arr.length(); i++) {
            String v = arr.optString(i, "").trim().toLowerCase(Locale.US);
            if (!v.isEmpty()) target.add(v);
        }
    }

    static String normalizeHost(String host) {
        String h = host == null ? "" : host.trim().toLowerCase(Locale.US);
        while (h.endsWith(".")) h = h.substring(0, h.length() - 1);
        return h;
    }

    static String hostOf(String url) {
        try {
            java.net.URI uri = java.net.URI.create(url);
            return normalizeHost(uri.getHost() == null ? "" : uri.getHost());
        } catch (Exception e) {
            return "";
        }
    }

    private static boolean hostMatches(String host, Set<String> domains) {
        String h = normalizeHost(host);
        if (h.isEmpty()) return false;
        if (domains.contains(h)) return true;
        for (String d : domains) {
            if (h.endsWith("." + d)) return true;
        }
        return false;
    }

    public boolean isPlayerHost(String host) {
        return hostMatches(host, playerDomains)
            || hostMatches(host, declaredPlayerHosts)
            || hostMatches(host, hoppedPlayerHosts);
    }

    /**
     * Whether a page on this host may open one more player hop.
     *
     * <p>Only hosts trusted before this session qualify: the baked list, and what
     * our own play page declared. A host that was itself reached by hopping does
     * not, so trust never compounds — see {@link #hoppedPlayerHosts}.
     */
    public boolean mayOpenPlayerHop(String host) {
        return hostMatches(host, playerDomains) || hostMatches(host, declaredPlayerHosts);
    }

    /**
     * Remember a player host our own play page declared, for this session only.
     *
     * <p>Session-scoped on purpose: nothing is written to disk, so a hostile
     * page cannot permanently widen the allow-list, and a rotation self-heals on
     * the next play instead of waiting for a new build.
     *
     * <p>Still refused for advert hosts — see {@link #remember}.
     */
    public boolean trustDeclaredPlayerUrl(String url) {
        return remember(url, declaredPlayerHosts, "declared by the play page");
    }

    /**
     * Remember one sibling host reached by hopping out of a trusted player page.
     *
     * <p>Refused when the page doing the hopping is not itself trusted
     * ({@link #mayOpenPlayerHop}), when the hop ceiling is already reached, and
     * for advert hosts — see {@link #remember}.
     */
    public boolean trustHoppedPlayerUrl(String initiatorHost, String url) {
        if (!mayOpenPlayerHop(initiatorHost)) return false;
        return remember(url, hoppedPlayerHosts, "player hop from " + initiatorHost);
    }

    /**
     * Admit one embedded player carrying the same media identifier as its parent.
     *
     * <p>The BI player is a full-window iframe: /e/{id} embeds a rotated host's
     * /{route}/{id}. Android reports that request as a subframe, so the top-frame
     * hop rule never saw it and the shield returned an empty 404. A shared media
     * id allows that handover without trusting arbitrary third-party scripts or
     * adverts requested by the outer page. The child is a hopped host and cannot
     * authorize another hop. Query tokens are intentionally not part of the id.
     */
    public boolean trustEmbeddedPlayerUrl(String initiatorUrl, String url) {
        try {
            java.net.URI parent = java.net.URI.create(initiatorUrl == null ? "" : initiatorUrl);
            java.net.URI child = java.net.URI.create(url == null ? "" : url);
            if (!"https".equalsIgnoreCase(parent.getScheme())
                    || !"https".equalsIgnoreCase(child.getScheme())
                    || parent.getUserInfo() != null || child.getUserInfo() != null
                    || !mayOpenPlayerHop(parent.getHost())) return false;
            String parentPath = parent.getRawPath();
            String childPath = child.getRawPath();
            if (parentPath == null || childPath == null) return false;
            // Only explicit embed documents may introduce a sibling. Restrict
            // identifiers to a single opaque segment (no escaped slashes).
            java.util.regex.Matcher media = java.util.regex.Pattern
                    .compile("^/(?:e|embed)/([A-Za-z0-9_-]{4,128})/?$")
                    .matcher(parentPath);
            if (!media.matches()) return false;
            String id = media.group(1);
            if (!childPath.matches("^/[A-Za-z0-9_-]{1,32}/"
                    + java.util.regex.Pattern.quote(id) + "/?$")) return false;
            return remember(url, hoppedPlayerHosts, "matching embedded media from " + parent.getHost());
        } catch (IllegalArgumentException e) {
            return false;
        }
    }

    private boolean remember(String url, Set<String> target, String why) {
        String host = hostOf(url == null ? "" : url);
        if (host.isEmpty()) return false;
        // The advert tables outrank every route into this method. Learning must
        // never be a way around the block list — otherwise a page only has to
        // talk us into trusting a host once and the ad network is in.
        if (isAdUrl(url)) {
            Log.i(TAG, "refusing to learn an advert host: " + host);
            return false;
        }
        // Already trusted by the baked list: nothing to record, but the caller
        // should not read that as a refusal.
        if (hostMatches(host, playerDomains)) return true;
        if (target.size() >= MAX_LEARNED_HOSTS && !target.contains(host)) {
            Log.w(TAG, "learned-host ceiling reached, refusing: " + url);
            return false;
        }
        if (target.add(host)) {
            Log.i(TAG, "player host learned (" + why + "): " + host);
        }
        return true;
    }

    /** Whether this host is one the session learned, by either route. */
    public boolean isLearnedPlayerHost(String host) {
        return hostMatches(host, declaredPlayerHosts) || hostMatches(host, hoppedPlayerHosts);
    }

    public boolean isAssetHost(String host) {
        return hostMatches(host, assetDomains);
    }

    /** Mirrors ShieldPolicy.is_ad_url: host tables first, then URL keywords
     * as label-boundary matches (never path substrings like /tags/affiliate). */
    public boolean isAdUrl(String url) {
        String raw = url == null ? "" : url;
        String host = hostOf(raw);
        if (host.isEmpty()) return true;
        if (isPlayerHost(host) || isAssetHost(host)) return false;
        if (hostMatches(host, blockedHosts)) return true;
        String lowered = raw.toLowerCase(Locale.US);
        for (String token : blockUrlKeywords) {
            if (token.isEmpty()) continue;
            if (token.indexOf('.') >= 0 && token.indexOf('/') < 0) {
                if (hostMatches(host, java.util.Collections.singleton(token))) return true;
            }
            if (matchesLabel(lowered, token)) return true;
        }
        return false;
    }

    private static boolean matchesLabel(String url, String token) {
        int idx = url.indexOf(token);
        while (idx >= 0) {
            char before = idx == 0 ? '/' : url.charAt(idx - 1);
            int end = idx + token.length();
            char after = end >= url.length() ? '/' : url.charAt(end);
            if (isBoundary(before) && isBoundary(after)) return true;
            idx = url.indexOf(token, idx + 1);
        }
        return false;
    }

    private static boolean isBoundary(char c) {
        switch (c) {
            case '/': case '?': case '#': case '.': case '_': case '=':
            case '&': case '-':
                return true;
            default:
                return false;
        }
    }

    private boolean isAppHost(String host) {
        return appOrigins.contains(normalizeHost(host));
    }

    /** Main-frame / iframe navigation gate. true = block. */
    public boolean shouldBlockNavigation(String url) {
        String raw = url == null ? "" : url.trim();
        if (raw.isEmpty()) return false;
        String scheme = "";
        int colon = raw.indexOf(':');
        if (colon > 0) scheme = raw.substring(0, colon).toLowerCase(Locale.US);
        if (!scheme.equals("http") && !scheme.equals("https")) return false;
        String host = hostOf(raw);
        if (isAdUrl(raw)) {
            blockedNavigations++;
            return true;
        }
        // The app origin (local viewer) plus site/player domains may navigate.
        if (isAppHost(host) || isPlayerHost(host)) return false;
        // Everything else (ad redirect targets, link farms) is blocked and
        // counted, matching desktop navigation_decision's cross-origin gate.
        blockedNavigations++;
        return true;
    }

    /** Media file URLs may come from short-lived CDN hosts — allowed by
     * extension regardless of host, mirroring the desktop media policy. */
    private static boolean isMediaUrl(String url) {
        String lower = url.toLowerCase(Locale.US);
        int q = lower.indexOf('?');
        if (q >= 0) lower = lower.substring(0, q);
        return lower.endsWith(".m3u8") || lower.endsWith(".mpd")
            || lower.endsWith(".mp4") || lower.endsWith(".webm")
            || lower.endsWith(".m4s") || lower.endsWith(".ts")
            || lower.endsWith(".m4a") || lower.endsWith(".mp3")
            || lower.endsWith(".flac") || lower.endsWith(".ogg")
            || lower.endsWith(".wav") || lower.endsWith(".aac");
    }

    /** Subresource gate used by shouldInterceptRequest — the lightweight
     * in-app player browser. Mirrors the desktop allow-list policy:
     * site/player/cover/app hosts plus bare media CDN URLs are allowed,
     * everything else (ads, trackers, unrelated third-party scripts and
     * frames) is dropped so pages load fast and clean. blob:/data:/about:
     * stay untouched so MediaSource players and bootstrap iframes work. */
    public WebResourceResponse intercept(WebView view, WebResourceRequest request) {
        android.net.Uri u = request.getUrl();
        String url = u == null ? "" : u.toString();
        String scheme = u == null ? "" : String.valueOf(u.getScheme()).toLowerCase(Locale.US);
        if (!scheme.equals("http") && !scheme.equals("https")) return null;
        String host = hostOf(url);
        boolean allowed = isAppHost(host) || isPlayerHost(host) || isAssetHost(host)
            || isMediaUrl(url);
        if (allowed && !isAdUrl(url)) return null;
        blockedRequests++;
        Log.i(TAG, "blocked request #" + blockedRequests + ": " + url);
        // The top-level document is the one request that must never be answered
        // with an empty body. An empty 404 on the main frame is a white screen
        // with no explanation — indistinguishable from a broken app, and it is
        // exactly what a rotated player host used to produce. A refusal the user
        // can read is a five-second fix; a blank page is a support ticket.
        if (request.isForMainFrame()) return blockedPage(host);
        return blockedResponse();
    }

    /** Subresource refusal: empty and cheap, and the page never shows it. */
    public static WebResourceResponse blockedResponse() {
        try {
            return new WebResourceResponse(
                "text/plain", "utf-8", 404, "Blocked",
                null, new ByteArrayInputStream(new byte[0]));
        } catch (Exception e) {
            return null;
        }
    }

    /**
     * Main-frame refusal, as a page the user can actually read.
     *
     * <p>It names the host, because that host is the thing to add to
     * {@code PLAYER_DOMAINS} when a player rotates, and it offers the only
     * action that helps: go back to the page that sent them.
     *
     * <p>Every colour comes from {@link Theme}, the same source the rest of the
     * shell paints from. The application deliberately uses its dark palette,
     * including on devices whose system theme is light, so a blocked player
     * cannot flash a white page during playback.
     */
    private static WebResourceResponse blockedPage(String host) {
        String body =
            "<!doctype html><meta name=viewport content='width=device-width,initial-scale=1'>"
          + "<title>已拦截</title><style>"
          + ":root{color-scheme:dark;"
          + "--bg:" + Theme.BG_CSS + ";--surface:" + Theme.SURFACE_CSS + ";"
          + "--text:" + Theme.TEXT_CSS + ";--text-2:" + Theme.TEXT_2_CSS + ";"
          + "--accent:" + Theme.ACCENT_CSS + ";--on-accent:" + Theme.ON_ACCENT_CSS + ";"
          + "--danger:" + Theme.DANGER_CSS + ";--danger-soft:" + Theme.DANGER_SOFT_CSS + ";"
          + "--sep:" + Theme.SEP_CSS + "}"
          + "html,body{margin:0;height:100%}"
          + "body{display:flex;align-items:center;justify-content:center;padding:24px;"
          + "background:var(--bg);color:var(--text);-webkit-font-smoothing:antialiased;"
          + "font:15px/1.5 -apple-system,BlinkMacSystemFont,'Segoe UI','PingFang SC',"
          + "'Microsoft YaHei',system-ui,sans-serif}"
          + ".card{width:100%;max-width:400px;box-sizing:border-box;padding:28px 24px;"
          + "border:1px solid var(--sep);border-radius:20px;background:var(--surface);"
          + "text-align:center}"
          + ".badge{display:inline-block;padding:4px 10px;border-radius:999px;font-size:11px;"
          + "letter-spacing:.04em;font-weight:600;color:var(--danger);background:var(--danger-soft)}"
          + "h1{margin:14px 0 0;font-size:19px;line-height:1.3}"
          + "p{margin:10px 0 0;color:var(--text-2);font-size:13.5px}"
          + "code{display:block;margin:16px 0 0;padding:11px 12px;border-radius:12px;"
          + "background:var(--bg);border:1px solid var(--sep);color:var(--accent);"
          + "font:12.5px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;word-break:break-all}"
          + "button{margin-top:20px;width:100%;padding:14px 16px;border:0;border-radius:14px;"
          + "background:var(--accent);color:var(--on-accent);font:inherit;font-size:15px;"
          + "font-weight:600;cursor:pointer}"
          + "button:active{opacity:.82}"
          + "</style><div class=card><span class=badge>广告盾拦截</span>"
          + "<h1>这个地址不在白名单里</h1>"
          + "<code>" + escapeHtml(host) + "</code>"
          + "<p>如果是播放器换了域名，把上面这个域名加进白名单就能恢复播放。</p>"
          + "<button onclick=\"history.back()\">返回上一页</button></div>";
        try {
            return new WebResourceResponse("text/html", "utf-8", 200, "Blocked",
                java.util.Collections.singletonMap("Cache-Control", "no-store"),
                new ByteArrayInputStream(body.getBytes("UTF-8")));
        } catch (Exception e) {
            return blockedResponse();
        }
    }

    private static String escapeHtml(String raw) {
        if (raw == null) return "";
        return raw.replace("&", "&amp;").replace("<", "&lt;")
                  .replace(">", "&gt;").replace("\"", "&quot;");
    }
}
